import{_ as a,c as n,a as r,o as c}from"./app-gY-7qYtG.js";const i={};function d(p,e){return c(),n("div",null,e[0]||(e[0]=[r('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-08-05-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-08-05-资讯日报"><span>2026-08-05 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="于开丞创业做概念世界模型获过亿融资" tabindex="-1"><a class="header-anchor" href="#于开丞创业做概念世界模型获过亿融资"><span>于开丞创业做概念世界模型获过亿融资</span></a></h3><p>于开丞：2023 年做世界模型被视为天方夜谭，如今成热门。他否定过往工作，提出“概念世界模型”解决泛化难题。其创办的西湖数智已获超 1 亿融资，将按三步构建模型能力。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86fa5419a5333f571105c8ca28e84ed0818ede14a4871163c5c26b4d05cd95f97302bdce5f22&amp;idx=1&amp;mid=2649802038&amp;sn=e01ea6f6f90d689a7f1fbdf560525bad#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="国内首个ai生成内容合规标准征参编单位" tabindex="-1"><a class="header-anchor" href="#国内首个ai生成内容合规标准征参编单位"><span>国内首个AI生成内容合规标准征参编单位</span></a></h3><p>中国电子商会、智合标准中心等联合推出全国首个AI生成内容合规团体标准，解决责任虚化、技术无标等问题，现面向全行业征集起草单位与专家。<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=86751ac44e04d799c06914a99c3771d80b39a07d4fc9cfad25eaf27566aeee4ea011a0448f51&amp;idx=1&amp;mid=2461160727&amp;sn=d4539959a07dbb314dbba7223586bff2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="uber-ai好用但太贵-限额审查搞起来" tabindex="-1"><a class="header-anchor" href="#uber-ai好用但太贵-限额审查搞起来"><span>Uber：AI好用但太贵，限额审查搞起来</span></a></h3><p>Uber：‘零增长技术栈’优化基础设施，集成AI提升开发效率，92%工程师在用。但成本增长六倍，于是限额开发者费用，还审查代码效果，用新指标评估效率。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc2c182bc910d2b79bb094c619cea0326171187302a2a6fba1901beebcfc3f814c8a1f7c0211&amp;idx=4&amp;mid=2651290057&amp;sn=3e192f36a87a31aeb7c75f39bc26b26a#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="数学家24小时驳回openai攻破的猜想" tabindex="-1"><a class="header-anchor" href="#数学家24小时驳回openai攻破的猜想"><span>数学家24小时驳回OpenAI攻破的猜想</span></a></h3><p>OpenAI称新模型推翻Connes刚性猜想，堪萨斯大学J. L. Nielsen次日反驳，指出AI构造群不满足条件，还逐行核对代码找问题。强调人类审查对AI科研结果至关重要，猜想仍待解。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e905de61b508dfe0d5a01a1d0e0733aa9a8162cd8128b9269f5bae8d0d595c14ea4d025c15dd&amp;idx=2&amp;mid=2247909606&amp;sn=d56afc5b7366234acbe886280269020d#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai挖来黑客「祖师爷」护安全" tabindex="-1"><a class="header-anchor" href="#openai挖来黑客「祖师爷」护安全"><span>OpenAI挖来黑客「祖师爷」护安全</span></a></h3><p>OpenAI近期疯狂“集邮式”抢人，黑客“祖师爷”Halvar Flake官宣入职。他在安全领域成果丰硕，加入或因GPT系列安全事件频发，为AI安全再上“保险”。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0a58b6b45db5552006dc79efdb4256812243f31f53474b6680e70b487a276f26ec7487f8b08&amp;idx=1&amp;mid=2652716363&amp;sn=a09498947c782b269cb210417e33a63c#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="马斯克-ai直出二进制-大佬集体回怼" tabindex="-1"><a class="header-anchor" href="#马斯克-ai直出二进制-大佬集体回怼"><span>马斯克：AI直出二进制，大佬集体回怼</span></a></h3><p>马斯克称AI可直出二进制，摒弃源代码，引发争议。UML之父等大佬回怼，指出AI生成代码有不确定性。但现实中AI生成代码比例渐高，争论核心是人类能否信任看不懂的工程体系。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0a876fcef26e3a0cd162d995dfffe4ef9c0c1209dafaadcd59864a1fbd82b40e159d88ba670&amp;idx=2&amp;mid=2652716406&amp;sn=11a3bb5f9e968e81c982ce395a790e12#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="aicon深圳2026-聚焦agent工程化新路径" tabindex="-1"><a class="header-anchor" href="#aicon深圳2026-聚焦agent工程化新路径"><span>AICon深圳2026：聚焦Agent工程化新路径</span></a></h3><p>AICon深圳2026大会8月21 - 22日举办。学界与产业专家将围绕工业具身智能等方向演讲。还设多技术专题，企业一线专家分享AI在业务场景的工程实践。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc9d9f111633be1dbf8a1ced13e4cc2ff65328eb5fd0dd488cd734276fc85277e84a3342c524&amp;idx=1&amp;mid=2651290057&amp;sn=f4885bd595c5898744d4afdacf423a83#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_2026-中国-agi-创新影响力机构-top-30-发布" tabindex="-1"><a class="header-anchor" href="#_2026-中国-agi-创新影响力机构-top-30-发布"><span>2026 中国 AGI 创新影响力机构 TOP 30 发布</span></a></h3><p>Founder Park 发布 2026 「中国 AGI 创新影响力机构 TOP 30」。AI 行业发展超模型层，这些机构横跨多领域，如 DeepSeek 模型能力领先，可灵视频生成商业化成功，诺亦腾为具身智能提供数据。<a href="https://mp.weixin.qq.com/s?__biz=Mzg5NTc0MjgwMw==&amp;chksm=c19a9040259206427f0ad94e8e9b27ef9e66c6c6f3ba418be2277ab37b07d583af41ef12db4e&amp;idx=1&amp;mid=2247525675&amp;sn=8f52111082422dd5e16b741fca226e59#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="spacex财报-ai增收但盈利难" tabindex="-1"><a class="header-anchor" href="#spacex财报-ai增收但盈利难"><span>SpaceX财报：AI增收但盈利难</span></a></h3><p>SpaceX首份财报显示，AI业务收入增长迅猛成第二大收入源，但开支巨大仍亏损。马斯克预计AI发展提速，公司暂定明年底扩容。后续需解决客户消化、收支增速等问题。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9f76908f4e285ecd83cdc67e548ac331ba7874fea33adecfb55c331cfe55c312af9fe174af5&amp;idx=1&amp;mid=2247909814&amp;sn=996f84c5ba38c37e3a128b39cf3f06c9#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek低价风暴席卷硅谷-应用契机将至" tabindex="-1"><a class="header-anchor" href="#deepseek低价风暴席卷硅谷-应用契机将至"><span>DeepSeek低价风暴席卷硅谷，应用契机将至</span></a></h3><p>DeepSeek V4 Flash以低价优势打服硅谷，海外平台争相补贴。其能力提升显著，让更多开发者愿用开源模型。AI应用层现新契机，且DeepSeek Code可能快来了。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e938e9081a320d358fd80ff2664c9a503222c74ea4c3a82de3d59ce4b15572e297e1f8f6cd74&amp;idx=1&amp;mid=2247909606&amp;sn=ae3b7b0f8180c26cc409d7de8d4f547c#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="马斯克联手英伟达打造太空ai大脑" tabindex="-1"><a class="header-anchor" href="#马斯克联手英伟达打造太空ai大脑"><span>马斯克联手英伟达打造太空AI大脑</span></a></h3><p>马斯克携手英伟达推出轨道AI计算网络Starmind，要在太空建AI大脑，解决地球算力中心能耗、散热难题。他还计划借星舰和超级工厂量产卫星，终极目标是攀登卡尔达肖夫指数。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0a4e2cee424f9daa242064c361f4c957d1ab4b7513df09bb04851dccb2b0a20f638f211562e&amp;idx=1&amp;mid=2652716406&amp;sn=776c0537eeaabf8fb0fe43d283c9f5f5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="anthropic发布claude-opus-5-性能亮眼" tabindex="-1"><a class="header-anchor" href="#anthropic发布claude-opus-5-性能亮眼"><span>Anthropic发布Claude Opus 5，性能亮眼</span></a></h3><p>Anthropic推出Claude Opus 5，运行成本低且多任务表现优，在多项测试领先，解决了Fable 5部分问题。虽有易产生幻觉等不足，但对多数开发者是受欢迎的更新。<a href="https://mp.weixin.qq.com/s?__biz=MzIxNzI0ODE4Nw==&amp;chksm=964550d2da6c584849f3fc00a4457ad74467b0c6a6b23052e1eb66f0d76fc28553ef9a1f08e9&amp;idx=1&amp;mid=2247498700&amp;sn=75a4080e44409b7c70a60879d2f6cb66#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="阿里发布qwen3-8-编程16天造出智能体" tabindex="-1"><a class="header-anchor" href="#阿里发布qwen3-8-编程16天造出智能体"><span>阿里发布Qwen3.8，编程16天造出智能体</span></a></h3><p>阿里：8月3日发布Qwen3.8大模型，总参数量2.4万亿。它编程、办公能力强，能自主编程出Hermes Agent，适配真武M890超节点。‘千问办公’开启公测，API已上线且价格优。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc65038f5ea57438baade5db96d80a7d2484ccef961603ff7577f702f7b0da8995935f652a67&amp;idx=3&amp;mid=2651290057&amp;sn=0787bb81f0df18d55d0d961da497b813#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="张磊-世界模型需以动作为输入条件" tabindex="-1"><a class="header-anchor" href="#张磊-世界模型需以动作为输入条件"><span>张磊：世界模型需以动作为输入条件</span></a></h3><p>张磊：具身智能走向现实，要解决成功率和泛化能力问题，大脑更关键且难在机制未明。世界模型因能提供虚拟环境助机器人试错而火，其应具备动作依赖。团队在视觉模型基础上做世界模型有信心。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91f8a525ae6ef387e9aee09b2317e2c09ebc655dd8a9528abbeddaad2c0fd2108c8e1961e735&amp;idx=1&amp;mid=2247741005&amp;sn=92b258465f141f71a12712307ebcf29e#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="师天麾-agent-infra-爆发时机未到" tabindex="-1"><a class="header-anchor" href="#师天麾-agent-infra-爆发时机未到"><span>师天麾：Agent Infra 爆发时机未到</span></a></h3><p>清程极智师天麾：模型迭代快抑制企业对 Agent 投入，当前 Agent Infra 未到爆发阶段，要提高 Token 生产交付效率；还指出国产芯片需适配推理引擎，未来 Agent 或按结果收费。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc2a13a21b48f88a7a83ad65cbdd26000a16161332b50ce63d675ea937451f80641c3f4b5f7b&amp;idx=2&amp;mid=2651290057&amp;sn=38fbda3d9f67b7dccbfd45cfb92a85ab#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="_244行开源文档破解ai出图土气难题" tabindex="-1"><a class="header-anchor" href="#_244行开源文档破解ai出图土气难题"><span>244行开源文档破解AI出图土气难题</span></a></h3><p>开源项目<code>gc - minimal - zine - poster</code>：将日系zine感审美拆成模型可执行的指令，规定渲染问题、取值区间和自检规则，防止风格复制，适配多Agent，为AI出图提供新方法。<a href="https://mp.weixin.qq.com/s?__biz=MzAxNTA3MDY1NA==&amp;chksm=8dd588e40a144a443200a91b8786198e2839448d64b3422c6e54d11b3d923857582ea3ecc29b&amp;idx=2&amp;mid=2455895152&amp;sn=88544b251a50eefa4a64ea69db21c24c#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="qwen3-8-max下周开源-能力全面提升" tabindex="-1"><a class="header-anchor" href="#qwen3-8-max下周开源-能力全面提升"><span>Qwen3.8-Max下周开源，能力全面提升</span></a></h3><p>Qwen3.8-Max：2.4万亿参数，Qwen家族最强模型，下周开源。在多项测试表现优异，能连续自主工作，编程、办公、科研等能力全面提升，多模态能力贯穿任务全流程。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3Mzg5MjY3Nw==&amp;chksm=cf18091d4c690b9257c7dd5f8e16b598959c7b940310d27f8ada8b08ee5445e8f9d291169908&amp;idx=1&amp;mid=2247526670&amp;sn=204b863bff459f215821667c8b14bdb6#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="bento-开源ppt神器来袭" tabindex="-1"><a class="header-anchor" href="#bento-开源ppt神器来袭"><span>Bento：开源PPT神器来袭！</span></a></h3><p>Bento演示文稿：一个开源的PPT神器！它是HTML单文件，无需安装，功能超丰富，有实时协作、内置图表等，还支持和AI联用，本地模型也能用，构建简单。<a href="https://mp.weixin.qq.com/s?__biz=MzkxNjQ4MzMyOA==&amp;chksm=c03aff76e4b12d9bc3559ef4ac7131c1dc8be393c0ea77ebcdeb75c456e50648e7cae70b8369&amp;idx=1&amp;mid=2247495945&amp;sn=e4dfb84859a6029ac4dcdcf3e4c50977#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="面壁智能开源forgestencil-1周优化百款工业软件" tabindex="-1"><a class="header-anchor" href="#面壁智能开源forgestencil-1周优化百款工业软件"><span>面壁智能开源ForgeStencil，1周优化百款工业软件</span></a></h3><p>面壁智能联合OpenBMB开源ForgeStencil，实现Stencil优化「自动研究+自动部署」大闭环。1周自动优化100+真实应用，全程0人干预，加速多款工业软件，助力国产工业软件性能自主。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0ca410079cc88cda4ec5f290ea81bbbb140a7b6a3553c68277a39e4079bc0ac93d36f63bd65&amp;idx=1&amp;mid=2652716222&amp;sn=e66397c021855f63636c8383ecb6289a#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="卡兹克开源活人感写作-skill去ai味" tabindex="-1"><a class="header-anchor" href="#卡兹克开源活人感写作-skill去ai味"><span>卡兹克开源活人感写作.skill去AI味</span></a></h3><p>数字生命卡兹克：为让写作去AI味，开源活人感写作.skill。它能适配多模型产品，鼓励用真实经历创作，除辞章处理，还激发思想、验证事实，强调写作别丢自我。<a href="https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA==&amp;chksm=f1ec364350096af8906fd2e0148c657da682fbaab7c115cea91d8346ca4fad5149008bdbce50&amp;idx=1&amp;mid=2647684946&amp;sn=ae7edcc572b998dc4e1ac3591977aa85#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="大模型看图能力差-与人类有近-9-倍鸿沟" tabindex="-1"><a class="header-anchor" href="#大模型看图能力差-与人类有近-9-倍鸿沟"><span>大模型看图能力差，与人类有近 9 倍鸿沟</span></a></h3><p>作者团队发布 ActiveVision 测量大模型「主动观察」能力。评测显示，无工具时大模型与人类准确率差距近 9 倍；用工具虽提升但仍有距离，且使用工具代价大，瓶颈仅转移。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85368de30ca292395ea6c927c02e92eaac98c95a0283bc5e81573fb4af47add54179cda36199&amp;idx=2&amp;mid=2651048380&amp;sn=0ed98bd19c4dd5fde6f00883d086e147#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="gcea-yolo-油田抽烟检测精度提升20-8" tabindex="-1"><a class="header-anchor" href="#gcea-yolo-油田抽烟检测精度提升20-8"><span>GCEA - YOLO：油田抽烟检测精度提升20.8%</span></a></h3><p>科研人员：油田抽烟检测难题多，基于YOLOv11n构建GCEA - YOLO，四个模块针对性解决问题，精确率提升20.8%，兼顾计算量与实时性，为AI应用提供可行路径。<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTk3ODI2OA==&amp;chksm=861cf7b4f04a2941b24cfbf090b7f8695c84575362277993ce0101aa12acba445e7873cccb1c&amp;idx=1&amp;mid=2650365199&amp;sn=6eedd1fe94d2eab0dd65538dbab216d7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',53)]))}const l=a(i,[["render",d]]),s=JSON.parse('{"path":"/posts/2026-08-05.html","title":"AI日报：于开丞创业做概念世界模型获过亿融资; 国内首个AI生成内容合规标准征参编单位; Uber：AI好用但太贵，限额审查搞起来","lang":"zh-CN","frontmatter":{"date":"2026-08-05T00:00:00.000Z","title":"AI日报：于开丞创业做概念世界模型获过亿融资; 国内首个AI生成内容合规标准征参编单位; Uber：AI好用但太贵，限额审查搞起来"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"于开丞创业做概念世界模型获过亿融资","slug":"于开丞创业做概念世界模型获过亿融资","link":"#于开丞创业做概念世界模型获过亿融资","children":[]},{"level":3,"title":"国内首个AI生成内容合规标准征参编单位","slug":"国内首个ai生成内容合规标准征参编单位","link":"#国内首个ai生成内容合规标准征参编单位","children":[]},{"level":3,"title":"Uber：AI好用但太贵，限额审查搞起来","slug":"uber-ai好用但太贵-限额审查搞起来","link":"#uber-ai好用但太贵-限额审查搞起来","children":[]},{"level":3,"title":"数学家24小时驳回OpenAI攻破的猜想","slug":"数学家24小时驳回openai攻破的猜想","link":"#数学家24小时驳回openai攻破的猜想","children":[]},{"level":3,"title":"OpenAI挖来黑客「祖师爷」护安全","slug":"openai挖来黑客「祖师爷」护安全","link":"#openai挖来黑客「祖师爷」护安全","children":[]},{"level":3,"title":"马斯克：AI直出二进制，大佬集体回怼","slug":"马斯克-ai直出二进制-大佬集体回怼","link":"#马斯克-ai直出二进制-大佬集体回怼","children":[]},{"level":3,"title":"AICon深圳2026：聚焦Agent工程化新路径","slug":"aicon深圳2026-聚焦agent工程化新路径","link":"#aicon深圳2026-聚焦agent工程化新路径","children":[]},{"level":3,"title":"2026 中国 AGI 创新影响力机构 TOP 30 发布","slug":"_2026-中国-agi-创新影响力机构-top-30-发布","link":"#_2026-中国-agi-创新影响力机构-top-30-发布","children":[]},{"level":3,"title":"SpaceX财报：AI增收但盈利难","slug":"spacex财报-ai增收但盈利难","link":"#spacex财报-ai增收但盈利难","children":[]},{"level":3,"title":"DeepSeek低价风暴席卷硅谷，应用契机将至","slug":"deepseek低价风暴席卷硅谷-应用契机将至","link":"#deepseek低价风暴席卷硅谷-应用契机将至","children":[]},{"level":3,"title":"马斯克联手英伟达打造太空AI大脑","slug":"马斯克联手英伟达打造太空ai大脑","link":"#马斯克联手英伟达打造太空ai大脑","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"Anthropic发布Claude Opus 5，性能亮眼","slug":"anthropic发布claude-opus-5-性能亮眼","link":"#anthropic发布claude-opus-5-性能亮眼","children":[]},{"level":3,"title":"阿里发布Qwen3.8，编程16天造出智能体","slug":"阿里发布qwen3-8-编程16天造出智能体","link":"#阿里发布qwen3-8-编程16天造出智能体","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"张磊：世界模型需以动作为输入条件","slug":"张磊-世界模型需以动作为输入条件","link":"#张磊-世界模型需以动作为输入条件","children":[]},{"level":3,"title":"师天麾：Agent Infra 爆发时机未到","slug":"师天麾-agent-infra-爆发时机未到","link":"#师天麾-agent-infra-爆发时机未到","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"244行开源文档破解AI出图土气难题","slug":"_244行开源文档破解ai出图土气难题","link":"#_244行开源文档破解ai出图土气难题","children":[]},{"level":3,"title":"Qwen3.8-Max下周开源，能力全面提升","slug":"qwen3-8-max下周开源-能力全面提升","link":"#qwen3-8-max下周开源-能力全面提升","children":[]},{"level":3,"title":"Bento：开源PPT神器来袭！","slug":"bento-开源ppt神器来袭","link":"#bento-开源ppt神器来袭","children":[]},{"level":3,"title":"面壁智能开源ForgeStencil，1周优化百款工业软件","slug":"面壁智能开源forgestencil-1周优化百款工业软件","link":"#面壁智能开源forgestencil-1周优化百款工业软件","children":[]},{"level":3,"title":"卡兹克开源活人感写作.skill去AI味","slug":"卡兹克开源活人感写作-skill去ai味","link":"#卡兹克开源活人感写作-skill去ai味","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"大模型看图能力差，与人类有近 9 倍鸿沟","slug":"大模型看图能力差-与人类有近-9-倍鸿沟","link":"#大模型看图能力差-与人类有近-9-倍鸿沟","children":[]},{"level":3,"title":"GCEA - YOLO：油田抽烟检测精度提升20.8%","slug":"gcea-yolo-油田抽烟检测精度提升20-8","link":"#gcea-yolo-油田抽烟检测精度提升20-8","children":[]}]}],"git":{"updatedTime":1785911092000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"680f5f210c79d5edeaf3ad1364d14aec2838c491","time":1785911092000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-08-05T06:24:52.385Z"}]},"filePathRelative":"posts/2026-08-05.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-08-05 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>于开丞创业做概念世界模型获过亿融资</h3>\\n<p>于开丞：2023 年做世界模型被视为天方夜谭，如今成热门。他否定过往工作，提出“概念世界模型”解决泛化难题。其创办的西湖数智已获超 1 亿融资，将按三步构建模型能力。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86fa5419a5333f571105c8ca28e84ed0818ede14a4871163c5c26b4d05cd95f97302bdce5f22&amp;idx=1&amp;mid=2649802038&amp;sn=e01ea6f6f90d689a7f1fbdf560525bad#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{l as comp,s as data};
